import { NFTSRecord } from "@/types/rewards";
import { Button } from "@/components/ui/button";
import { DownloadSolid, Edit } from "@mynaui/icons-react";
import useDialogStore from "@/stores/dialog-store";
import { cn } from "@/lib/utils";
import { useState } from "react";
import { HeaderWrapper } from "../custom/header-wrapper";
import Image from "next/image";

const details = [
  { label: "Award Date", value: "Feb 25, 2025" },
  { label: "Type of Award", value: "Campaign Winner" },
];

const personalDetails = [
  { label: "Username", value: "SmartCircus" },
  { label: "Wallet", value: "9H7XWqE2r1B5YvKjkhq3n8v7TcdPzMoJfHxuAWfhqXg" },
  { label: "Status", value: "Awarded" },
  { label: "Transaction Hash", value: "qE2r1B5YvKjkhq3n8v7H7XWqE2r1B7TCdPq6B5YvKjkhq3n" },
];

export function NftDetail() {
  const { setNftsEdit } = useDialogStore();
  const [isEdit, setIsEdit] = useState(true);

  return (
    <div className="font-WFVisualSansRegular bg-[#232226]">
      <Image
        src={"/board.svg"}
        alt="board"
        width={500}
        height={300}
        className="w-full"
      />
      <div className="p-6 flex flex-col gap-6">
        {/* Header Information */}
        <div>
          <span className="uppercase text-xs leading-5 tracking-[3px]">
            Campaign Winner
          </span>
          <h1 className="text-2xl leading-10">
            SmartCircus NFT Award
          </h1>
          <span className="gap-2 text-xs inline">
            Status:{" "}
            <span className="text-primary">
              Awarded
            </span>
          </span>
        </div>

        {/* Stats */}
        <div>
          <div className="bg-[#1d1c21] text-center gap-4 p-4 py-8 rounded-xl flex justify-between px-8 max-md:flex-col">
            <span className="space-y-2">
              <div className="text-3xl">9H7XWqE2r1B5YvKjkhq3n8v7TcdPzMoJfHxuAWfhqXg</div>
              <p className="text-custom-light_text text-xs">Wallet Address</p>
            </span>
            <hr className="min-w-[2px] h-full bg-custom-slate" />
            <span className="space-y-2">
              <div className="text-3xl flex justify-center items-center">
                qE2r1B5YvKjkhq3n8v7H7XWqE2r1B7TCdPq6B5YvKjkhq3n
              </div>
              <p className="text-custom-light_text text-xs">
                Transaction Hash
              </p>
            </span>
          </div>
        </div>

        {/* Detail Like Country,.... */}
        <div className="flex flex-wrap gap-x-10 gap-y-5 text-sm border-b border-[#323138] pb-5">
          {details?.map((item, key) => (
            <div key={key} className="flex flex-col">
              <span className="tex-xs">{item?.value}</span>
              <span className="text-xs text-gray-400">{item?.label}</span>
            </div>
          ))}
        </div>

        {/* Wallet Information */}
        <div>
          <p className="text-primary !break-words line-clamp-1 text-xs">
            9H7XWqE2r1B5YvKjkhq3n8v7TcdPzMoJfHxuAWfhqXg
            <br />
            <span className="text-muted-foreground text-xs">
              NFT Wallet
            </span>
          </p>
          <Button variant={"link"} size={"sm"} className="text-xs">
            <DownloadSolid />
            Download NFT
          </Button>
        </div>

        {/* User Information */}
        <div className="flex flex-wrap justify-between items-center border-b border-[#323138] pb-4 space-y-5 gap-x-10 text-sm">
          {personalDetails?.map((item, key) => (
            <div key={key} className="flex flex-col">
              <span className="">{item?.value}</span>
              <span className="text-gray-400">{item?.label}</span>
            </div>
          ))}
        </div>

        {/* Actions */}
        <div className="space-y-4">
          <div className="flex gap-2">
            <Button className="bg-primary hover:bg-primary/90">
              View in Solanart
            </Button>
            <Button variant="destructive" className="bg-destructive hover:bg-destructive/90">
              Revoke NFT
            </Button>
          </div>
        </div>

        {/* Edit Button */}
        <Button
          size={"lg"}
          onClick={() => setNftsEdit(true)}
          className={cn("text-lg ml-auto", !isEdit && "hidden")}
          rounded={"xl"}
        >
          Edit
          <Edit className="!w-6 !h-6" />
        </Button>

        <HeaderWrapper
          size={"sm"}
          title={
            <div className="tracking-wider">
              Updates -{" "}
              <span className="text-muted-foreground">
                Professional Media by CharCoin
              </span>
            </div>
          }
          description={
            <span className="text-xs">
              Videos uploaded in this section will show up to all benefactors that
              voted for this project.
            </span>
          }
        />
      </div>
    </div>
  );
} 