import { create } from "zustand";

interface DialogState {
  openDialog: "causes_add" | "causes_edit" | "causes_detail" | "community_news_add" | "community_news_edit" | "community_news_detail" | "administration_add" | "administration_edit" | "administration_detail" | "wallet_settings_add" | "wallet_settings_edit" | "wallet_settings_detail" | "nfts_detail" | "nfts_edit" | null;
  setOpenDialog: (dialog: DialogState["openDialog"]) => void;
  setCausesAdd: (open: boolean) => void;
  setCausesEdit: (open: boolean) => void;
  setCausesDetail: (open: boolean) => void;
  setCommunityNewsAdd: (open: boolean) => void;
  setCommunityNewsEdit: (open: boolean) => void;
  setCommunityNewsDetail: (open: boolean) => void;
  setAdministrationAdd: (open: boolean) => void;
  setAdministrationEdit: (open: boolean) => void;
  setAdministrationDetail: (open: boolean) => void;
  setWalletSettingsAdd: (open: boolean) => void;
  setWalletSettingsEdit: (open: boolean) => void;
  setWalletSettingsDetail: (open: boolean) => void;
  setNftsDetail: (open: boolean) => void;
  setNftsEdit: (open: boolean) => void;
}

const useDialogStore = create<DialogState>((set) => ({
  openDialog: null,
  setOpenDialog: (dialog) => set({ openDialog: dialog }),
  setCausesAdd: (open) => set({ openDialog: open ? "causes_add" : null }),
  setCausesEdit: (open) => set({ openDialog: open ? "causes_edit" : null }),
  setCausesDetail: (open) => set({ openDialog: open ? "causes_detail" : null }),
  setCommunityNewsAdd: (open) => set({ openDialog: open ? "community_news_add" : null }),
  setCommunityNewsEdit: (open) => set({ openDialog: open ? "community_news_edit" : null }),
  setCommunityNewsDetail: (open) => set({ openDialog: open ? "community_news_detail" : null }),
  setAdministrationAdd: (open) => set({ openDialog: open ? "administration_add" : null }),
  setAdministrationEdit: (open) => set({ openDialog: open ? "administration_edit" : null }),
  setAdministrationDetail: (open) => set({ openDialog: open ? "administration_detail" : null }),
  setWalletSettingsAdd: (open) => set({ openDialog: open ? "wallet_settings_add" : null }),
  setWalletSettingsEdit: (open) => set({ openDialog: open ? "wallet_settings_edit" : null }),
  setWalletSettingsDetail: (open) => set({ openDialog: open ? "wallet_settings_detail" : null }),
  setNftsDetail: (open) => set({ openDialog: open ? "nfts_detail" : null }),
  setNftsEdit: (open) => set({ openDialog: open ? "nfts_edit" : null }),
}));

export default useDialogStore;
