import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useRef, useState } from "react";
import { ChevronDown, Trash2, UploadCloud } from "lucide-react";

const campaigns = [
  {
    value: "april-2025",
    label: "April 2025 (From April 1 to April 20) - Awarded the 25th",
  },
];

const types = [
  { value: "winner", label: "Campaign Winner" },
];

export default function NftCreateForm() {
  const [image, setImage] = useState<string | null>(
    "/nft-preview.png"
  );
  const fileInputRef = useRef<HTMLInputElement>(null);

  return (
    <div className="font-WFVisualSansRegular bg-[#232226] p-8 w-full max-w-xl">
      {/* Header */}
      <div className="mb-8">
        <h2 className="text-2xl font-semibold mb-1">Create a new Official NFT</h2>
        <p className="text-sm text-muted-foreground">
          Complete the following fields to create and mint a new NFT
        </p>
      </div>
      <hr className="border-[#323138] mb-8" />
      {/* Main details */}
      <div className="mb-8">
        <h3 className="text-lg font-medium mb-6">Main details</h3>
        <div className="mb-6">
          <label className="block text-sm mb-1">NFT Name</label>
          <span className="block text-xs text-gray-400 mb-2">
            This is the public NFT name
          </span>
          <Input
            className="bg-[#323138] border-none text-white mb-4"
            value="Elzie - The Doctor"
            readOnly
          />
          <label className="block text-sm mb-1">Description</label>
          <span className="block text-xs text-gray-400 mb-2">
            Describe the visuals found on the NFT
          </span>
          <Input
            className="bg-[#323138] border-none text-white mb-4"
            value="A beautiful pixel-art style of our Elzie dressed as a doctor"
            readOnly
          />
          <label className="block text-sm mb-1">NFT image</label>
          <span className="block text-xs text-gray-400 mb-2">
            Choose a 1000x600 pixels PNG image, below you will see a preview of the uploaded image
          </span>
          <div className="flex items-end gap-6 mb-4">
            <div className="flex flex-col gap-2">
              <Button
                className="bg-[#1ff2e9] text-black hover:bg-[#1ff2e9]/90"
                onClick={() => fileInputRef.current?.click()}
                type="button"
              >
                <UploadCloud className="w-4 h-4 mr-2" /> Upload an image
              </Button>
              <Button
                className="bg-[#1ff2e9] text-black hover:bg-[#1ff2e9]/90"
                type="button"
              >
                <Trash2 className="w-4 h-4 mr-2" /> Delete Image
              </Button>
              <input
                ref={fileInputRef}
                type="file"
                accept="image/png,image/jpeg"
                className="hidden"
                onChange={() => {}}
              />
            </div>
            {image && (
              <img
                src={image}
                alt="NFT Preview"
                className="rounded-lg w-48 h-48 object-cover border border-[#323138]"
              />
            )}
          </div>
        </div>
      </div>
      <div className="flex gap-8 mb-8">
        <div className="flex-1">
          <label className="block text-sm mb-1">Type of NFT</label>
          <span className="block text-xs text-gray-400 mb-2">
            Choose the correct awarding method
          </span>
          <div className="relative">
            <select
              className="w-full bg-[#323138] text-white rounded-md py-2 pl-3 pr-8 appearance-none border-none"
              value={types[0].value}
              readOnly
            >
              {types.map((type) => (
                <option key={type.value} value={type.value}>
                  {type.label}
                </option>
              ))}
            </select>
            <ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
          </div>
        </div>
        <div className="flex-1">
          <label className="block text-sm mb-1">Campaign</label>
          <span className="block text-xs text-gray-400 mb-2">
            Choose the campaign when this NFT will be awarded randomly
          </span>
          <div className="relative">
            <select
              className="w-full bg-[#323138] text-white rounded-md py-2 pl-3 pr-8 appearance-none border-none"
              value={campaigns[0].value}
              readOnly
            >
              {campaigns.map((c) => (
                <option key={c.value} value={c.value}>
                  {c.label}
                </option>
              ))}
            </select>
            <ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
          </div>
        </div>
      </div>
      <hr className="border-[#323138] mb-8" />
      <p className="text-xs text-gray-400 mb-8">
        A new NFT will be minted within the OpenSea ecosystem as part of the official CharCoin collection. This NFT will remain under CharCoin's ownership until it is transferred to the randomly selected winner of the month. Each NFT carries a 10% intellectual property royalty on every transaction, supporting the CharCoin community. The NFT will be awarded as a gift to a CharCoin ecosystem user who has completed at least one transaction during the campaign month. The winner will be announced and credited on the 25th of the campaign month.
      </p>
      <Button className="bg-[#1ff2e9] text-black hover:bg-[#1ff2e9]/90 w-full text-lg py-6 rounded-xl">
        Mint NFT in Solanart <span className="ml-2">→</span>
      </Button>
    </div>
  );
} 